import json
import math
import time
from collections import Counter
from collections.abc import Mapping
from importlib.metadata import PackageNotFoundError, version
from numbers import Integral

import networkx as nx
import numpy as np
from qiskit import QuantumCircuit, transpile
from qiskit.circuit import ParameterVector
from qiskit_aer import AerSimulator
from scipy.optimize import minimize


def _positive_integer(name, value):
    if isinstance(value, bool) or not isinstance(value, Integral) or value < 1:
        raise ValueError(f"{name} must be a positive integer.")
    return int(value)


def _canonical_bits(bits):
    """Identify complementary partitions; the first vertex always has label 0."""
    bits = tuple(int(bit) for bit in bits)
    return bits if bits[0] == 0 else tuple(1 - bit for bit in bits)


def _partition_groups(vertices, bits):
    return {
        "group_0": [v for v, bit in zip(vertices, bits) if bit == 0],
        "group_1": [v for v, bit in zip(vertices, bits) if bit == 1],
    }


def _parse_reference_partition(reference, vertices):
    """
    Accept None, a vertex-to-label mapping, two collections of vertex names,
    a mapping from two group names to vertex collections, or labels in vertex
    order. A binary string is also accepted in vertex order, not Qiskit order.
    """
    if reference is None:
        return None

    n = len(vertices)
    vertex_set = set(vertices)

    if isinstance(reference, Mapping):
        if set(reference) == vertex_set:
            labels = [reference[v] for v in vertices]
            groups = None
        elif len(reference) == 2:
            groups = list(reference.values())
            labels = None
        else:
            raise ValueError("Reference mapping must assign every vertex.")
    else:
        values = list(reference)
        collection_types = (list, tuple, set, frozenset, np.ndarray)
        if len(values) == 2 and all(
            isinstance(group, collection_types) for group in values
        ):
            groups = values
            labels = None
        elif len(values) == n:
            groups = None
            labels = values
        else:
            raise ValueError("Invalid reference partition format.")

    if groups is not None:
        assignment = {}
        for label, group in enumerate(groups):
            for vertex in group:
                if vertex not in vertex_set:
                    raise ValueError(f"Unknown reference vertex: {vertex!r}")
                if vertex in assignment:
                    raise ValueError("Reference groups overlap or repeat vertices.")
                assignment[vertex] = label
        if set(assignment) != vertex_set:
            raise ValueError("Reference partition must contain every vertex.")
        labels = [assignment[v] for v in vertices]

    label_ids = {}
    bits = []
    for label in labels:
        try:
            if label not in label_ids:
                label_ids[label] = len(label_ids)
            bits.append(label_ids[label])
        except TypeError as exc:
            raise ValueError("Reference labels must be hashable.") from exc

    if len(label_ids) != 2:
        raise ValueError("Reference partition must have exactly two nonempty groups.")
    return _canonical_bits(bits)


def _make_evaluator(n, indexed_edges, degrees, lambda_balance, lambda_cut):
    """
    Density is operationalized using Newman-Girvan modularity, with normalized
    cut-fraction and balance regularization. Normalized cut is reported
    separately: its volume-dependent denominators are not a quadratic QUBO.

    Minimize:
        L = 1 - Q + lambda_cut * cut_edges / m + lambda_balance * B

    where:
        B = ((n0 - n1)^2 - (n mod 2)) / (n^2 - (n mod 2)).

    Thus B=0 for the most balanced possible split, including odd vertex counts.
    Adding 1 makes the loss nonnegative without changing its minimizer.
    Empty groups are excluded from the final answer, although the standard
    unconstrained QAOA state can contain their bitstrings.
    """
    m = len(indexed_edges)
    parity = n % 2
    balance_denominator = n * n - parity
    cache = {}

    def evaluate(bits):
        bits = _canonical_bits(bits)
        if bits in cache:
            return cache[bits]

        n1 = sum(bits)
        n0 = n - n1
        cut_edges = sum(bits[u] != bits[v] for u, v in indexed_edges)
        volume_0 = sum(degrees[i] for i, bit in enumerate(bits) if bit == 0)
        volume_1 = 2 * m - volume_0

        if m:
            cut_fraction = cut_edges / m
            modularity = (
                1.0
                - cut_fraction
                - (volume_0 / (2.0 * m)) ** 2
                - (volume_1 / (2.0 * m)) ** 2
            )
        else:
            # For an edgeless graph, modularity is defined here as zero.
            cut_fraction = 0.0
            modularity = 0.0

        # An isolated, zero-volume group contributes zero by convention.
        normalized_cut = (
            cut_edges / volume_0 if volume_0 > 0 else 0.0
        ) + (
            cut_edges / volume_1 if volume_1 > 0 else 0.0
        )

        balance_penalty = (
            (n0 - n1) ** 2 - parity
        ) / balance_denominator

        result = {
            "modularity_score": float(modularity),
            "normalized_cut_score": float(normalized_cut),
            "balance_constraint_score": float(1.0 - balance_penalty),
            "objective_value": float(
                1.0
                - modularity
                + lambda_cut * cut_fraction
                + lambda_balance * balance_penalty
            ),
            "cut_edges": int(cut_edges),
            "group_sizes": [int(n0), int(n1)],
        }
        cache[bits] = result
        return result

    return evaluate


def _ising_terms(adjacency, degrees, lambda_balance, lambda_cut):
    """
    For z_i=(-1)^x_i, the loss is offset + sum_{i<j} J_ij z_i z_j.
    Modularity satisfies Q = z.T @ (A - dd.T/(2m)) @ z / (4m).
    """
    n = len(degrees)
    m = float(np.sum(degrees) / 2.0)
    parity = n % 2
    denominator = n * n - parity

    offset = 1.0 + lambda_balance * (n - parity) / denominator
    if m:
        offset += lambda_cut / 2.0
        offset += float(np.dot(degrees, degrees)) / (8.0 * m * m)

    terms = []
    for i in range(n):
        for j in range(i + 1, n):
            coefficient = 2.0 * lambda_balance / denominator
            if m:
                modularity_matrix_entry = (
                    adjacency[i, j] - degrees[i] * degrees[j] / (2.0 * m)
                )
                coefficient -= modularity_matrix_entry / (2.0 * m)
                coefficient -= lambda_cut * adjacency[i, j] / (2.0 * m)
            if abs(coefficient) > 1e-15:
                terms.append((i, j, float(coefficient)))

    return terms, float(offset)


def _build_qaoa_circuit(n, p_layers, terms):
    gamma = ParameterVector("gamma", p_layers)
    beta = ParameterVector("beta", p_layers)

    circuit = QuantumCircuit(n)
    circuit.h(range(n))
    for layer in range(p_layers):
        for i, j, coefficient in terms:
            # RZZ(theta) = exp(-i theta Z_i Z_j / 2).
            circuit.rzz(2.0 * coefficient * gamma[layer], i, j)
        for i in range(n):
            circuit.rx(2.0 * beta[layer], i)
    circuit.measure_all()
    return circuit, gamma, beta


def _decode_counts(counts, n):
    """Qiskit strings are q_(n-1)...q_0; returned tuples use vertex order."""
    decoded = Counter()
    for bitstring, count in counts.items():
        value = int(bitstring.replace(" ", ""), 2)
        bits = tuple((value >> i) & 1 for i in range(n))
        decoded[_canonical_bits(bits)] += int(count)
    return decoded


def _local_polish(initial_bits, evaluate):
    """
    Deterministic best-improvement refinement using single-vertex moves and
    cross-group swaps. Exhaustive benchmark solutions are never used here.
    """
    current = _canonical_bits(initial_bits)
    n = len(current)

    while True:
        neighbors = set()

        for i in range(n):
            candidate = list(current)
            candidate[i] ^= 1
            if 0 < sum(candidate) < n:
                neighbors.add(_canonical_bits(candidate))

        for i in range(n):
            for j in range(i + 1, n):
                if current[i] != current[j]:
                    candidate = list(current)
                    candidate[i], candidate[j] = candidate[j], candidate[i]
                    neighbors.add(_canonical_bits(candidate))

        if not neighbors:
            return current

        best = min(
            neighbors,
            key=lambda bits: (evaluate(bits)["objective_value"], bits),
        )
        if (
            evaluate(best)["objective_value"]
            < evaluate(current)["objective_value"] - 1e-12
        ):
            current = best
        else:
            return current


def _exact_benchmark(n, evaluate, maximum_vertices=16):
    """
    Certify the minimum loss over all nonempty bipartitions for small graphs.
    Fixing the first bit to zero removes complementary duplicates. This is
    benchmarking only, not a source of candidates for the hybrid algorithm.
    """
    if n > maximum_vertices:
        return None

    best_bits = None
    best_value = math.inf
    for mask in range(1, 1 << (n - 1)):
        bits = (0,) + tuple((mask >> (i - 1)) & 1 for i in range(1, n))
        value = evaluate(bits)["objective_value"]
        if value < best_value or (
            value == best_value and (best_bits is None or bits < best_bits)
        ):
            best_bits = bits
            best_value = value

    return {
        "bits": best_bits,
        "objective_value": float(best_value),
        "partitions_evaluated": (1 << (n - 1)) - 1,
    }


def _package_versions():
    versions = {}
    for package in ("qiskit", "qiskit-aer", "numpy", "scipy", "networkx"):
        try:
            versions[package] = version(package)
        except PackageNotFoundError:
            versions[package] = "unknown"
    return versions


def solve_graph_partition_qaoa(
    graph_vertices,
    graph_edges,
    known_reference_partition,
    p_layers=1,
    lambda_balance=0.8,
    lambda_cut=3.5,
    opt_shots=256,
    final_shots=1024,
    maxiter=40,
    n_repro_runs=3,
    seed=42,
):
    """
    Run shot-based QAOA plus classical local refinement on an unweighted graph.

    All supplied relationships are single undirected edges. Publication counts
    and relationship categories do not imply additional numerical weights.

    Required scores:
      modularity_score: Newman-Girvan modularity; higher is better.
      normalized_cut_score: cut/volume_0 + cut/volume_1; lower is better.
      balance_constraint_score: 1-B, with 1 denoting optimal size balance.
      approximation_ratio: returned loss / exact minimum loss, a minimization
          ratio with optimum 1. Exact certification is limited to 16 vertices.
          Larger instances return None rather than claim an unverified ratio.
      runtime: total wall-clock seconds, including all runs and benchmarking.
      reproducibility: independent seeded runs, agreement, settings, versions.

    The reference partition is evaluated only after optimization and is never
    used to initialize, train, select, or refine the QAOA solution. A reference
    partition alone does not prove optimality.

    This is a small-graph statevector demonstrator, not a quantum-speedup claim.
    """
    start_time = time.perf_counter()

    p_layers = _positive_integer("p_layers", p_layers)
    opt_shots = _positive_integer("opt_shots", opt_shots)
    final_shots = _positive_integer("final_shots", final_shots)
    maxiter = _positive_integer("maxiter", maxiter)
    n_repro_runs = _positive_integer("n_repro_runs", n_repro_runs)

    if (
        isinstance(seed, bool)
        or not isinstance(seed, Integral)
        or seed < 0
    ):
        raise ValueError("seed must be a nonnegative integer.")
    seed = int(seed)

    lambda_balance = float(lambda_balance)
    lambda_cut = float(lambda_cut)
    if not math.isfinite(lambda_balance) or lambda_balance < 0:
        raise ValueError("lambda_balance must be finite and nonnegative.")
    if not math.isfinite(lambda_cut) or lambda_cut < 0:
        raise ValueError("lambda_cut must be finite and nonnegative.")

    vertices = list(graph_vertices)
    n = len(vertices)
    if n < 2:
        raise ValueError("At least two vertices are required.")
    if len(set(vertices)) != n:
        raise ValueError("Vertex names must be unique and hashable.")

    index = {vertex: i for i, vertex in enumerate(vertices)}
    indexed_edges = set()
    for edge in graph_edges:
        endpoints = tuple(edge)
        if len(endpoints) != 2:
            raise ValueError("Each edge must contain exactly two vertices.")
        u, v = endpoints
        if u not in index or v not in index:
            raise ValueError(f"Edge contains an unknown vertex: {endpoints!r}")
        if u == v:
            raise ValueError("Self-loops are not collaboration pairs.")
        indexed_edges.add(tuple(sorted((index[u], index[v]))))
    indexed_edges = tuple(sorted(indexed_edges))

    graph = nx.Graph()
    graph.add_nodes_from(vertices)
    graph.add_edges_from((vertices[u], vertices[v]) for u, v in indexed_edges)
    adjacency = nx.to_numpy_array(graph, nodelist=vertices, dtype=float)
    degrees = adjacency.sum(axis=1)

    reference_bits = _parse_reference_partition(
        known_reference_partition, vertices
    )
    evaluate = _make_evaluator(
        n, indexed_edges, degrees, lambda_balance, lambda_cut
    )
    terms, hamiltonian_offset = _ising_terms(
        adjacency, degrees, lambda_balance, lambda_cut
    )
    template, gamma, beta = _build_qaoa_circuit(n, p_layers, terms)

    seed_sequences = np.random.SeedSequence(seed).spawn(n_repro_runs)
    run_results = []

    for run_index, sequence in enumerate(seed_sequences):
        run_start = time.perf_counter()
        generated_seeds = sequence.generate_state(4, dtype=np.uint32)
        initialization_seed, optimization_seed, sampling_seed, transpiler_seed = (
            int(value) for value in generated_seeds
        )
        rng = np.random.default_rng(initialization_seed)

        backend = AerSimulator(
            method="statevector",
            max_parallel_threads=1,
        )
        compiled = transpile(
            template,
            backend=backend,
            optimization_level=1,
            seed_transpiler=transpiler_seed,
        )

        def sample(parameters, shots, simulator_seed):
            bindings = {}
            for layer in range(p_layers):
                bindings[gamma[layer]] = float(parameters[layer])
                bindings[beta[layer]] = float(parameters[p_layers + layer])
            # A zero Hamiltonian can remove unused gamma parameters.
            bound = compiled.assign_parameters(
                bindings, inplace=False, strict=False
            )
            counts = backend.run(
                bound,
                shots=shots,
                seed_simulator=simulator_seed,
            ).result().get_counts()
            return _decode_counts(counts, n)

        evaluation_count = 0

        def expected_loss(parameters):
            nonlocal evaluation_count
            evaluation_count += 1
            # Common random numbers reduce shot-noise variability across
            # parameter evaluations while preserving deterministic replay.
            counts = sample(parameters, opt_shots, optimization_seed)
            return float(
                sum(
                    count * evaluate(bits)["objective_value"]
                    for bits, count in counts.items()
                ) / sum(counts.values())
            )

        initial_parameters = np.concatenate(
            (
                rng.uniform(0.0, 2.0 * np.pi, p_layers),
                rng.uniform(0.0, np.pi, p_layers),
            )
        )
        optimization = minimize(
            expected_loss,
            initial_parameters,
            method="COBYLA",
            bounds=(
                [(0.0, 2.0 * np.pi)] * p_layers
                + [(0.0, np.pi)] * p_layers
            ),
            options={
                "maxiter": maxiter,
                "rhobeg": 0.5,
                "tol": 1e-3,
            },
        )

        final_counts = sample(
            optimization.x, final_shots, sampling_seed
        )
        feasible_counts = {
            bits: count
            for bits, count in final_counts.items()
            if 0 < sum(bits) < n
        }

        used_classical_fallback = not feasible_counts
        if feasible_counts:
            sampled_bits = min(
                feasible_counts,
                key=lambda bits: (evaluate(bits)["objective_value"], bits),
            )
        else:
            # Explicit feasible fallback if every measured state is empty
            # on one side; it does not use the reference or exact benchmark.
            sampled_bits = tuple(
                0 if i < (n + 1) // 2 else 1 for i in range(n)
            )

        polished_bits = _local_polish(sampled_bits, evaluate)
        metrics = evaluate(polished_bits)
        run_results.append(
            {
                "run_index": run_index,
                "bits": polished_bits,
                "partition": _partition_groups(vertices, polished_bits),
                "initialization_seed": initialization_seed,
                "optimization_simulator_seed": optimization_seed,
                "final_simulator_seed": sampling_seed,
                "transpiler_seed": transpiler_seed,
                "optimized_parameters": {
                    "gamma": optimization.x[:p_layers].tolist(),
                    "beta": optimization.x[p_layers:].tolist(),
                },
                "optimizer_success": bool(optimization.success),
                "optimizer_message": str(optimization.message),
                "objective_evaluations": evaluation_count,
                "optimized_sample_mean_loss": float(optimization.fun),
                "final_sample_mean_loss": float(
                    sum(
                        count * evaluate(bits)["objective_value"]
                        for bits, count in final_counts.items()
                    ) / sum(final_counts.values())
                ),
                "feasible_shot_fraction": (
                    sum(feasible_counts.values()) / final_shots
                ),
                "used_classical_fallback": used_classical_fallback,
                "best_sampled_objective": evaluate(sampled_bits)[
                    "objective_value"
                ],
                **metrics,
                "runtime": float(time.perf_counter() - run_start),
            }
        )

    best_run = min(
        run_results,
        key=lambda run: (
            run["objective_value"], run["bits"], run["run_index"]
        ),
    )
    best_bits = best_run["bits"]
    best_metrics = evaluate(best_bits)

    # Benchmark only after the hybrid solution has been selected.
    exact = _exact_benchmark(n, evaluate)
    if exact is not None:
        approximation_ratio = (
            best_metrics["objective_value"] / exact["objective_value"]
        )
        if math.isclose(approximation_ratio, 1.0, abs_tol=1e-12):
            approximation_ratio = 1.0
        certificate = {
            "certified": True,
            "method": "exhaustive nonempty bipartition enumeration",
            "partitions_evaluated": exact["partitions_evaluated"],
            "optimal_objective_value": exact["objective_value"],
            "optimal_partition": _partition_groups(vertices, exact["bits"]),
            "optimal_modularity_score": evaluate(exact["bits"])[
                "modularity_score"
            ],
        }
    else:
        approximation_ratio = None
        certificate = {
            "certified": False,
            "reason": "Exact certification is limited to at most 16 vertices.",
        }

    reference_report = None
    if reference_bits is not None:
        reference_metrics = evaluate(reference_bits)
        reference_report = {
            "partition": _partition_groups(vertices, reference_bits),
            **reference_metrics,
            # This can be below 1 if the supplied reference is suboptimal.
            "solution_to_reference_loss_ratio": (
                best_metrics["objective_value"]
                / reference_metrics["objective_value"]
            ),
            "is_certified_optimal": (
                math.isclose(
                    reference_metrics["objective_value"],
                    exact["objective_value"],
                    rel_tol=1e-10,
                    abs_tol=1e-12,
                )
                if exact is not None else None
            ),
        }

    partition_frequencies = Counter(run["bits"] for run in run_results)
    modularities = [run["modularity_score"] for run in run_results]
    losses = [run["objective_value"] for run in run_results]

    reproducibility = {
        "master_seed": seed,
        "n_runs": n_repro_runs,
        "selected_run_index": best_run["run_index"],
        "all_runs_same_partition": len(partition_frequencies) == 1,
        "selected_partition_frequency": (
            partition_frequencies[best_bits] / n_repro_runs
        ),
        "modal_partition_frequency": (
            max(partition_frequencies.values()) / n_repro_runs
        ),
        "modularity_mean": float(np.mean(modularities)),
        "modularity_std": float(np.std(modularities)),
        "objective_mean": float(np.mean(losses)),
        "objective_std": float(np.std(losses)),
        "settings": {
            "p_layers": p_layers,
            "lambda_balance": lambda_balance,
            "lambda_cut": lambda_cut,
            "opt_shots": opt_shots,
            "final_shots": final_shots,
            "maxiter": maxiter,
            "optimizer": "SciPy COBYLA",
            "backend": "qiskit_aer.AerSimulator",
            "simulation_method": "statevector with shot-based measurements",
            "max_parallel_threads": 1,
            "local_refinement": "single-vertex moves and cross-group swaps",
        },
        "package_versions": _package_versions(),
        "replay_note": (
            "Identical inputs, seeds, software versions and platform reproduce "
            "the sampled workflow; wall-clock timings are not reproducible. "
            "Agreement across these runs is descriptive, not a confidence bound."
        ),
        "runs": [
            {key: value for key, value in run.items() if key != "bits"}
            for run in run_results
        ],
    }

    result = {
        "modularity_score": best_metrics["modularity_score"],
        "normalized_cut_score": best_metrics["normalized_cut_score"],
        "balance_constraint_score": best_metrics["balance_constraint_score"],
        "approximation_ratio": approximation_ratio,
        "runtime": None,
        "reproducibility": reproducibility,
        "partition": _partition_groups(vertices, best_bits),
        "assignments": {
            vertex: int(bit) for vertex, bit in zip(vertices, best_bits)
        },
        "graph": {
            "vertices": vertices,
            "edges": [
                [vertices[u], vertices[v]] for u, v in indexed_edges
            ],
            "directed": False,
            "weighted": False,
        },
        "objective_value": best_metrics["objective_value"],
        "cut_edges": best_metrics["cut_edges"],
        "group_sizes": best_metrics["group_sizes"],
        "hamiltonian_constant_offset": hamiltonian_offset,
        "optimality_certificate": certificate,
        "reference_partition_evaluation": reference_report,
        "metric_definitions": {
            "modularity_score": "sum_g [internal_edges_g/m - (volume_g/(2m))^2]",
            "normalized_cut_score": (
                "cut_edges/volume_0 + cut_edges/volume_1; "
                "a zero-volume term contributes zero"
            ),
            "balance_constraint_score": (
                "1 - ((n0-n1)^2 - n%2)/(n^2 - n%2); "
                "1 means the most balanced possible group sizes"
            ),
            "objective_value": (
                "1 - modularity_score + lambda_cut*(cut_edges/m) "
                "+ lambda_balance*(1-balance_constraint_score); minimized"
            ),
            "approximation_ratio": (
                "objective_value/exact_optimal_objective_value; "
                "minimization convention, optimal value 1"
            ),
            "runtime": "total wall-clock seconds",
        },
    }
    result["runtime"] = float(time.perf_counter() - start_time)
    return result


if __name__ == "__main__":
    graph_vertices = ["R1", "R2", "R3", "R4", "R5"]
    graph_edges = [
        ["R1", "R2"],
        ["R1", "R3"],
        ["R2", "R3"],
        ["R3", "R4"],
        ["R4", "R5"],
    ]

    # This reference is reported and independently checked, never used to train
    # or select the solution. For this split Q=0.22 and normalized cut=10/21.
    reference_partition = [["R1", "R2", "R3"], ["R4", "R5"]]

    output = solve_graph_partition_qaoa(
        graph_vertices,
        graph_edges,
        known_reference_partition=reference_partition,
    )
    print(json.dumps(output, indent=2))

